<?php declare(strict_types=1);$title='Selecionar conta';require BASE_PATH.'/app/Views/admin/_top.php';?>
<section class="page-heading"><div><p class="eyebrow">Conexão <?= e($integration['provider']) ?></p><h1>Selecione a conta de anúncios</h1><p>A seleção é validada novamente no servidor.</p></div></section>
<section class="admin-panel"><form action="<?= e(base_url('admin/marketing/integracoes/'.$integration['id'].'/selecionar-conta')) ?>" method="post" class="account-picker"><?= csrf_field() ?><?php foreach($accounts as$account):?><label><input type="radio" name="conta_externa_id" value="<?= e($account['external_id']) ?>" required><span><strong><?= e($account['name']) ?></strong><small><?= e($account['external_id']) ?> · <?= e($account['currency']?:'moeda não informada') ?> · <?= e($account['timezone']?:'fuso não informado') ?><?= !empty($account['business_name'])?' · '.$account['business_name']:'' ?></small></span></label><?php endforeach;?><?php if($assets['pages']):?><label>Página<select name="page_external_id"><option value="">Não selecionar</option><?php foreach($assets['pages']as$page):?><option value="<?= e($page['id']??'') ?>"><?= e($page['name']??$page['id']??'') ?></option><?php endforeach;?></select></label><?php endif;?><?php if($assets['pixels']):?><label>Pixel ou dataset<select name="pixel_external_id"><option value="">Não selecionar</option><?php foreach($assets['pixels']as$pixel):?><option value="<?= e($pixel['id']??$pixel['pixel_id']??'') ?>"><?= e($pixel['name']??$pixel['pixel_name']??$pixel['id']??'') ?></option><?php endforeach;?></select></label><?php endif;?><button class="admin-primary">Usar esta conta</button></form><?php if(!$accounts):?><div class="empty-state"><p>Nenhuma conta acessível foi retornada. Verifique permissões e acesso aos ativos.</p></div><?php endif;?></section>
<?php require BASE_PATH.'/app/Views/admin/_bottom.php';?>
